import React, { useState, useEffect } from "react";

export default function JapTracker() {
  const STORAGE_KEY = "japTrackerData";

  const [days, setDays] = useState([]);
  const [showReminder, setShowReminder] = useState(false);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setDays(JSON.parse(saved));
    } else {
      const initial = Array.from({ length: 30 }, () => ({
        jap: false,
        satsang: false,
        prarthana: false
      }));
      setDays(initial);
    }

    // Daily reminder popup
    const lastShown = localStorage.getItem("reminderDate");
    const today = new Date().toDateString();

    if (lastShown !== today) {
      setShowReminder(true);
      localStorage.setItem("reminderDate", today);
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    if (days.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(days));
    }
  }, [days]);

  const toggle = (index, field) => {
    const updated = [...days];
    updated[index][field] = !updated[index][field];
    setDays(updated);
  };

  // Completed days
  const completedDays = days.filter(
    d => d.jap && d.satsang && d.prarthana
  ).length;

  // 🔥 Streak logic
  const streak = (() => {
    let count = 0;
    for (let i = 0; i < days.length; i++) {
      if (days[i].jap && days[i].satsang && days[i].prarthana) {
        count++;
      } else {
        break;
      }
    }
    return count;
  })();

  const progressPercent = Math.round((completedDays / 30) * 100);

  return (
    <div style={container}>
      <h3>📿 30-Day Jap Tracker</h3>

      {/* 🔔 Reminder Popup */}
      {showReminder && (
        <div style={reminder}>
          🙏 Jap time thayu!  
          <br />
          Bas 10 minute.
          <button onClick={() => setShowReminder(false)} style={btn}>
            OK
          </button>
        </div>
      )}

      {/* 🟢 Progress Ring */}
      <div style={ringContainer}>
        <svg width="120" height="120">
          <circle
            cx="60"
            cy="60"
            r="50"
            stroke="#eee"
            strokeWidth="10"
            fill="none"
          />
          <circle
            cx="60"
            cy="60"
            r="50"
            stroke="green"
            strokeWidth="10"
            fill="none"
            strokeDasharray={314}
            strokeDashoffset={314 - (314 * progressPercent) / 100}
            transform="rotate(-90 60 60)"
          />
          <text x="50%" y="50%" dominantBaseline="middle" textAnchor="middle">
            {progressPercent}%
          </text>
        </svg>
      </div>

      <p>🔥 Streak: <b>{streak} days</b></p>
      <p>✅ Completed: <b>{completedDays}/30</b></p>

      {/* 🎯 Badge */}
      {completedDays === 30 && (
        <div style={badge}>
          🎉 30/30 Complete! Krupa thai 🙏
        </div>
      )}

      {/* Table */}
      <div style={{ overflowX: "auto" }}>
        <table style={table}>
          <thead>
            <tr>
              <th>Day</th>
              <th>Jap</th>
              <th>Satsang</th>
              <th>Prarthana</th>
            </tr>
          </thead>

          <tbody>
            {days.map((d, i) => (
              <tr key={i}>
                <td>{i + 1}</td>

                <td onClick={() => toggle(i, "jap")} style={cell}>
                  {d.jap ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "satsang")} style={cell}>
                  {d.satsang ? "✔️" : "⬜"}
                </td>

                <td onClick={() => toggle(i, "prarthana")} style={cell}>
                  {d.prarthana ? "✔️" : "⬜"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const container = {
  background: "#fff",
  padding: "15px",
  borderRadius: "10px",
  marginTop: "20px"
};

const table = {
  width: "100%",
  borderCollapse: "collapse"
};

const cell = {
  cursor: "pointer",
  fontSize: "20px"
};

const ringContainer = {
  display: "flex",
  justifyContent: "center",
  margin: "10px 0"
};

const badge = {
  background: "gold",
  padding: "10px",
  borderRadius: "10px",
  textAlign: "center",
  fontWeight: "bold",
  marginBottom: "10px"
};

const reminder = {
  background: "#ffeeba",
  padding: "10px",
  borderRadius: "8px",
  marginBottom: "10px",
  textAlign: "center"
};

const btn = {
  marginTop: "8px",
  padding: "5px 10px",
  cursor: "pointer"
};
